style.css:
search {
    background: #B8860B !important;
    border-radius: 20px !important;
    color: white !important;
    font-weight: bold !important;
}

search-icon-legacy {
    background: #B8860B !important;
    border-radius: 50% !important;
}

ytd-player {
    box-shadow: 0px 4px 15px rgba(0, 0, 0, 0.5) !important;
    border-radius: 10px !important;
}

* {
    font-family: 'Shadow of Xizor', sans-serif !important;
}

video-title, ytp-play-button, button {
    text-shadow: 0px 0px 10px rgba(255, 215, 0, 0.8) !important;
}

yt-simple-endpoint img {
    border-radius: 15px !important;
    box-shadow: 0px 4px 10px rgba(255, 215, 0, 0.5) !important;
    transition: transform 0.3s ease-in-out !important;
}
yt-simple-endpoint img:hover {
    transform: scale(1.05) !important;
}

button {
    background: linear-gradient(45deg, #8B0000, #B8860B) !important;
    color: white !important;
    font-weight: bold !important;
    border-radius: 8px !important;
    transition: all 0.3s ease-in-out !important;
}
button:hover {
    transform: scale(1.1) !important;
    box-shadow: 0px 0px 15px rgba(255, 215, 0, 0.7) !important;
}

comments {
    background: rgba(255, 215, 0, 0.1) !important;
    padding: 10px !important;
    border-radius: 10px !important;
}
comment-text {
    color: white !important;
    font-size: 15px !important;
}

description {
    background: rgba(0, 0, 0, 0.7) !important;
    padding: 10px !important;
    border-radius: 10px !important;
    box-shadow: inset 0px 0px 10px rgba(255, 215, 0, 0.5) !important;
}
